css:
.pod-root * { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }
.pod-root { font-family: 'Pretendard', sans-serif; background: var(--pn-07090e, #07090e); color: var(--pn-f8fafc, #f8fafc); min-height: 100vh; padding: 32px 16px; display: flex; flex-direction: column; align-items: center; }
.pod-root .pod-container { width: 100%; max-width: 860px; }
.pod-root .pod-header { text-align: center; margin-bottom: 28px; }
.pod-root .pod-badge { display: inline-flex; align-items: center; gap: 6px; padding: 5px 12px; background: rgba(var(--pod-accent-rgb, 99,102,241), 0.15); border: 1px solid rgba(var(--pod-accent-rgb, 99,102,241), 0.4); border-radius: 9999px; font-size: 12px; font-weight: 800; color: var(--pod-accent, #818cf8); margin-bottom: 12px; }
.pod-root .pod-title { font-size: 26px; font-weight: 900; letter-spacing: -0.02em; color: var(--pn-ffffff, #fff); margin-bottom: 8px; }
.pod-root .pod-desc { font-size: 14px; color: #94a3b8; }

.pod-root .calc-card { background: var(--pn-111726, #111726); border: 1px solid var(--pn-ffffff-008, rgba(255,255,255,0.08)); border-radius: 28px; padding: 36px 32px; box-shadow: 0 20px 40px var(--pn-000000-05, rgba(0,0,0,0.5)); margin-bottom: 24px; }
.pod-root .grid-2col { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; }
@media (max-width: 768px) { .pod-root .grid-2col { grid-template-columns: 1fr; } .pod-root .calc-card { padding: 24px 20px; } }

.pod-root .control-group { margin-bottom: 22px; }
.pod-root .control-label { display: flex; justify-content: space-between; font-size: 13.5px; font-weight: 700; color: var(--pn-cbd5e1, #cbd5e1); margin-bottom: 10px; }
.pod-root .control-val { color: var(--pod-accent, #818cf8); font-weight: 900; }
.pod-root .range-slider { width: 100%; height: 6px; border-radius: 4px; background: var(--pn-1e293b, #1e293b); outline: none; -webkit-appearance: none; }
.pod-root .range-slider::-webkit-slider-thumb { -webkit-appearance: none; width: 20px; height: 20px; border-radius: 50%; background: var(--pod-accent, #6366f1); cursor: pointer; box-shadow: 0 0 12px rgba(var(--pod-accent-rgb, 99,102,241), 0.6); }

/* Result Gauge */
.pod-root .gauge-box { background: var(--pn-000000-03, rgba(0,0,0,0.3)); border: 1px solid var(--pn-ffffff-006, rgba(255,255,255,0.06)); border-radius: 24px; padding: 28px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.pod-root .gauge-months { font-size: 54px; font-weight: 900; color: #10b981; letter-spacing: -0.03em; line-height: 1.1; margin: 12px 0 6px; }
.pod-root .gauge-status { font-size: 13px; font-weight: 800; padding: 4px 12px; border-radius: 99px; }
.pod-root .status-safe { background: rgba(16,185,129,0.2); color: #34d399; }
.pod-root .status-warn { background: rgba(245,158,11,0.2); color: #fbbf24; }
.pod-root .status-danger { background: rgba(239,68,68,0.2); color: #f87171; }

.pod-root .net-burn-row { display: flex; justify-content: space-between; width: 100%; padding: 12px 0; border-top: 1px solid var(--pn-ffffff-008, rgba(255,255,255,0.08)); margin-top: 18px; font-size: 13px; color: #94a3b8; }
.pod-root .btn-magnet { width: 100%; padding: 15px; background: linear-gradient(135deg, var(--pod-accent, #6366f1), #a855f7); border: none; border-radius: 14px; font-size: 14.5px; font-weight: 900; color: #fff; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 20px; transition: all 0.2s; }
.pod-root .btn-magnet:hover { filter: brightness(1.1); transform: translateY(-1px); }
.pod-root{min-height:0;width:100%;max-width:100%;overflow-x:hidden;}

js:
function formatWon(num) {
      if (num >= 10000) {
        var eok = Math.floor(num / 10000);
        var man = num % 10000;
        return man > 0 ? eok + '억 ' + man.toLocaleString() + '만원' : eok + '억원';
      }
      return num.toLocaleString() + '만원';
    }

    function calculateRunway() {
      var cash = parseInt(document.getElementById('sliderCash').value);
      var expense = parseInt(document.getElementById('sliderExpense').value);
      var revenue = parseInt(document.getElementById('sliderRevenue').value);

      document.getElementById('valCash').innerText = formatWon(cash);
      document.getElementById('valExpense').innerText = formatWon(expense);
      document.getElementById('valRevenue').innerText = formatWon(revenue);

      var netBurn = expense - revenue;
      var netBurnEl = document.getElementById('netBurnVal');
      var monthsEl = document.getElementById('runwayMonths');
      var badgeEl = document.getElementById('runwayBadge');
      var dateEl = document.getElementById('exhaustDate');

      if (netBurn <= 0) {
        netBurnEl.innerText = '+' + formatWon(Math.abs(netBurn)) + ' / 월 (흑자)';
        netBurnEl.style.color = '#34d399';
        monthsEl.innerText = '∞ 무한대';
        monthsEl.style.color = '#34d399';
        badgeEl.className = 'gauge-status status-safe';
        badgeEl.innerText = '손익분기 달성 (Default Alive)';
        dateEl.innerText = '자금 고갈 위험 없음';
      } else {
        netBurnEl.innerText = '-' + formatWon(netBurn) + ' / 월';
        netBurnEl.style.color = '#f87171';
        var months = (cash / netBurn).toFixed(1);
        monthsEl.innerText = months + '개월';

        var targetDate = new Date();
        targetDate.setMonth(targetDate.getMonth() + Math.round(cash / netBurn));
        dateEl.innerText = targetDate.getFullYear() + '년 ' + (targetDate.getMonth() + 1) + '월';

        if (months >= 12) {
          monthsEl.style.color = '#10b981';
          badgeEl.className = 'gauge-status status-safe';
          badgeEl.innerText = '안정권 (1년 이상 여유)';
        } else if (months >= 6) {
          monthsEl.style.color = '#fbbf24';
          badgeEl.className = 'gauge-status status-warn';
          badgeEl.innerText = '경고 (투자유치 준비 필요)';
        } else {
          monthsEl.style.color = '#ef4444';
          badgeEl.className = 'gauge-status status-danger';
          badgeEl.innerText = '데스밸리 위험 (비용 감축 시급)';
        }
      }
    }

    document.querySelectorAll('.range-slider').forEach(function(slider) {
      slider.addEventListener('input', calculateRunway);
    });

    calculateRunway();
    if (window.lucide) lucide.createIcons();

    if (window.MazaTelemetry) {
      window.MazaTelemetry.init({ podId: 'runway' });
    }
